for r in b:
 row={k:r.get(k,'') for k in cols};row.update(evidence_version='324592d84ae4f482ac7249b9285c2ecdb53e3a68',status='B_draft_A_crosscheck_proposed',A_approval='reconciliation proposed; not yet explicitly approved',B_approval='B accepted source draft 2026-10-28; no approval of new changes inferred',source_sha256=sha(raw),reconciliation_note='Source rule retained; final joint freeze pending.')
 if row['one_example_suffices']=='n/a':row['one_example_suffices']='not_applicable'
 idx=int(r['item_id'].rsplit(':',1)[-1]);before=dict(row)
